<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Kanban Board</title>
  <style>
    :root {
      --bg: #f4f7fb;
      --panel: #ffffff;
      --text: #1d2939;
      --muted: #667085;
      --line: #e4e7ec;
      --accent: #465fff;
      --danger: #d92d20;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Arial, Helvetica, sans-serif;
      color: var(--text);
      background: var(--bg);
    }

    main {
      max-width: 1200px;
      margin: 0 auto;
      padding: 40px 22px;
    }

    h1 {
      margin: 0 0 24px;
      font-size: 30px;
    }

    .new-task {
      display: flex;
      gap: 10px;
      margin-bottom: 24px;
    }

    #new-card {
      flex: 1;
      min-width: 0;
      border: 1px solid #cfd4dc;
      border-radius: 10px;
      padding: 12px 14px;
      font: inherit;
      outline: none;
    }

    #new-card:focus {
      border-color: var(--accent);
      box-shadow: 0 0 0 3px rgba(70, 95, 255, .15);
    }

    #add-card {
      border: 0;
      border-radius: 10px;
      padding: 12px 18px;
      color: white;
      background: var(--accent);
      font: inherit;
      font-weight: 700;
      cursor: pointer;
    }

    #add-card:hover { background: #3448dc; }

    .board {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 18px;
    }

    .column {
      min-height: 420px;
      border: 1px solid var(--line);
      border-radius: 14px;
      background: #edf1f7;
      overflow: hidden;
    }

    .column-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 16px;
      background: var(--panel);
      border-bottom: 1px solid var(--line);
    }

    .column-header h2 {
      margin: 0;
      font-size: 16px;
    }

    .count {
      min-width: 26px;
      padding: 4px 8px;
      border-radius: 99px;
      color: var(--muted);
      background: #eef2f6;
      text-align: center;
      font-size: 13px;
      font-weight: 700;
    }

    .card-container {
      min-height: 350px;
      padding: 12px;
    }

    .card-container.drag-over {
      background: rgba(70, 95, 255, .08);
      outline: 2px dashed var(--accent);
      outline-offset: -6px;
    }

    .card {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 12px;
      margin-bottom: 10px;
      padding: 13px;
      border: 1px solid #e1e5eb;
      border-radius: 10px;
      background: var(--panel);
      box-shadow: 0 2px 5px rgba(16, 24, 40, .07);
      cursor: grab;
      word-break: break-word;
    }

    .card:active { cursor: grabbing; }

    .card.dragging {
      opacity: .45;
    }

    .card-title {
      line-height: 1.35;
    }

    .card-del {
      flex: 0 0 auto;
      border: 0;
      padding: 1px 5px;
      color: var(--danger);
      background: transparent;
      font-size: 20px;
      line-height: 1;
      cursor: pointer;
    }

    .card-del:hover { color: #a91b13; }

    @media (max-width: 720px) {
      .board { grid-template-columns: 1fr; }
      .column { min-height: 240px; }
      .card-container { min-height: 170px; }
    }
  </style>
</head>
<body>
  <main>
    <h1>Kanban Board</h1>

    <div class="new-task">
      <input id="new-card" type="text" placeholder="Add a task..." aria-label="New task">
      <button id="add-card" type="button">Add card</button>
    </div>

    <section class="board" aria-label="Kanban board">
      <section class="column" id="col-todo">
        <header class="column-header">
          <h2>To Do</h2>
          <span class="count">0</span>
        </header>
        <div class="card-container" aria-label="To Do cards"></div>
      </section>

      <section class="column" id="col-doing">
        <header class="column-header">
          <h2>Doing</h2>
          <span class="count">0</span>
        </header>
        <div class="card-container" aria-label="Doing cards"></div>
      </section>

      <section class="column" id="col-done">
        <header class="column-header">
          <h2>Done</h2>
          <span class="count">0</span>
        </header>
        <div class="card-container" aria-label="Done cards"></div>
      </section>
    </section>
  </main>

  <script>
    (() => {
      const STORAGE_KEY = "kanban-board-state-v1";
      const columns = [...document.querySelectorAll(".column")];
      const input = document.getElementById("new-card");
      const addButton = document.getElementById("add-card");
      let draggedCard = null;

      function makeId() {
        return "card-" + Date.now() + "-" + Math.random().toString(16).slice(2);
      }

      function createCard(title, id = makeId()) {
        const card = document.createElement("article");
        card.className = "card";
        card.id = id;
        card.draggable = true;

        const titleElement = document.createElement("span");
        titleElement.className = "card-title";
        titleElement.textContent = title;

        const deleteButton = document.createElement("button");
        deleteButton.className = "card-del";
        deleteButton.type = "button";
        deleteButton.setAttribute("aria-label", "Delete " + title);
        deleteButton.textContent = "×";

        deleteButton.addEventListener("click", () => {
          card.remove();
          saveBoard();
          updateCounts();
        });

        card.addEventListener("dragstart", event => {
          draggedCard = card;
          event.dataTransfer.effectAllowed = "move";
          event.dataTransfer.setData("text/plain", card.id);
          requestAnimationFrame(() => card.classList.add("dragging"));
        });

        card.addEventListener("dragend", () => {
          card.classList.remove("dragging");
          draggedCard = null;
          document.querySelectorAll(".card-container").forEach(container => {
            container.classList.remove("drag-over");
          });
        });

        card.append(titleElement, deleteButton);
        return card;
      }

      function updateCounts() {
        columns.forEach(column => {
          column.querySelector(".count").textContent =
            column.querySelectorAll(".card").length;
        });
      }

      function saveBoard() {
        const state = {};
        columns.forEach(column => {
          state[column.id] = [...column.querySelectorAll(".card")].map(card => ({
            id: card.id,
            title: card.querySelector(".card-title").textContent
          }));
        });
        localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
      }

      function restoreBoard() {
        try {
          const state = JSON.parse(localStorage.getItem(STORAGE_KEY));
          if (!state || typeof state !== "object") return;

          columns.forEach(column => {
            const container = column.querySelector(".card-container");
            const cards = Array.isArray(state[column.id]) ? state[column.id] : [];
            cards.forEach(item => {
              if (item && typeof item.title === "string") {
                container.appendChild(createCard(item.title, item.id || makeId()));
              }
            });
          });
        } catch (_) {
          localStorage.removeItem(STORAGE_KEY);
        }
        updateCounts();
      }

      function addCard() {
        const title = input.value.trim();
        if (!title) return;
        document.querySelector("#col-todo .card-container")
          .appendChild(createCard(title));
        input.value = "";
        saveBoard();
        updateCounts();
        input.focus();
      }

      addButton.addEventListener("click", addCard);
      input.addEventListener("keydown", event => {
        if (event.key === "Enter") addCard();
      });

      columns.forEach(column => {
        const container = column.querySelector(".card-container");

        container.addEventListener("dragover", event => {
          event.preventDefault();
          event.dataTransfer.dropEffect = "move";
          container.classList.add("drag-over");
        });

        container.addEventListener("dragleave", event => {
          if (!container.contains(event.relatedTarget)) {
            container.classList.remove("drag-over");
          }
        });

        container.addEventListener("drop", event => {
          event.preventDefault();
          container.classList.remove("drag-over");

          const cardId = event.dataTransfer.getData("text/plain");
          const card = draggedCard || document.getElementById(cardId);
          if (!card) return;

          container.appendChild(card);
          saveBoard();
          updateCounts();
        });
      });

      restoreBoard();
    })();
  </script>
</body>
</html>
